260\begin{proposition}[三种经典场]\label{prop:b1:electrostatics-gauss:three}
261\index{带电球体的场}\index{带电导线的场}\index{带电平面的场}
262\begin{enumerate}
263  \item 半径为 $R$ 的球体，电荷 $Q$ 均匀分布于其体积内：
264        外部：$E(r) = \dfrac{Q}{4\pi\varepsilon_0r^2}$（$r > R$） ---
265        如同全部电荷都集中于球心 --- 而在内部 $E(r) =
266        \dfrac{Qr}{4\pi\varepsilon_0R^3}$，从零开始线性增长；
267        在 $r = R$ 处连续。若电荷只分布于球面上，
268        则内部场为零。
269  \item 线电荷密度为 $\lambda$ 的无限长导线：$E(r) =
270        \dfrac{\lambda}{2\pi\varepsilon_0 r}$，沿径向。
271  \item 面电荷密度为 $\sigma$ 的无限大平面：$E = \dfrac{\sigma}{2\varepsilon_0}$
272        位于平面两侧，垂直于平面；当 $\sigma > 0$ 时指向远离平面的方向，
273        \emph{与距离无关}。穿过平面时，
274        法向分量跃变 $\sigma/\varepsilon_0$。
275\end{enumerate}
276\end{proposition}
